defmodule GalliumWeb.Components.Frame do
  @moduledoc """
  Frame component used as a top or bottom separator.

  The component supports two frame styles and the project color palette.
  """

  use GalliumWeb, :component

  attr :style, :atom, default: :style1, values: [:style1, :style2]
  attr :mode, :atom, default: :top, values: [:top, :bottom]
  attr :class, :string, default: nil
  attr :color, :atom, default: :light_muted, values: [:blue, :bronze, :light_muted, :olive]

  def frame(assigns) do
    assigns =
      assigns
      |> assign(:flip_style, if(assigns.mode == :bottom, do: "transform: scaleY(-1);", else: nil))
      |> assign(:svg_color, get_svg_color(assigns.color))

    ~H"""
